/* @autogenerated */

/** Id del panel de error: si ya existe, se sustituye su texto en lugar de apilar otro. */
export const CONFIG_FATAL_ERROR_ID = 'app-config-fatal-error';

/**
 * Pinta directamente en el DOM, sin Angular (que aún no ha arrancado), que la configuración no se pudo cargar.
 * Sustituye a la pantalla en blanco que deja un `phylax-config.json` ausente o mal formado.
 */
export function showConfigFatalError(url: string, reason: unknown, doc: Document = document): HTMLElement {
  let panel = doc.getElementById(CONFIG_FATAL_ERROR_ID);
  if (!panel) {
    panel = doc.createElement('div');
    panel.id = CONFIG_FATAL_ERROR_ID;
    panel.setAttribute('role', 'alert');
    panel.style.cssText =
      'position:fixed;inset:0;z-index:2147483647;display:flex;flex-direction:column;justify-content:center;' +
      'gap:12px;padding:32px;background:#fff;color:#1d1b20;font:16px/1.5 system-ui,sans-serif;';
    doc.body.appendChild(panel);
  }
  // textContent: el motivo puede traer HTML (p. ej. el index.html que sirve el servidor en lugar del JSON)
  const title = doc.createElement('strong');
  title.style.fontSize = '20px';
  title.textContent = `No se pudo cargar ${url}`;
  const detail = doc.createElement('code');
  detail.style.cssText = 'white-space:pre-wrap;word-break:break-word;color:#b3261e;';
  detail.textContent = describe(reason);
  const hint = doc.createElement('span');
  hint.textContent = 'Revisa que el fichero exista y sea un JSON válido, y recarga la página.';
  panel.replaceChildren(title, detail, hint);
  return panel;
}

function describe(reason: unknown): string {
  if (reason instanceof Error) {
    return reason.message;
  }
  return String(reason);
}
